WITH mods AS (SELECT cr, section_id FROM cr_modifies_section UNION SELECT cr, section_id FROM section_modified_by), packs AS (SELECT cr, pack_id FROM cr_in_pack UNION SELECT cr, pack_id FROM pack_member), anchor AS (SELECT id FROM document WHERE number = '{ANCHOR}' OR id = '{ANCHOR}') SELECT DISTINCT s1.clause AS clause, COALESCE(o.number, o.id) AS document, dp.code AS disposition, m.label AS wg_meeting, cp.pack_number AS cr_pack FROM anchor a JOIN mods ma ON ma.cr = a.id JOIN section s1 ON s1.id = ma.section_id AND ltrim(lower(trim(s1.release)),'release-_ v') = '19' JOIN section s2 ON s2.spec = s1.spec AND s2.release = s1.release AND s2.clause = s1.clause JOIN mods mo ON mo.section_id = s2.id JOIN document o ON o.id = mo.cr AND ltrim(lower(trim(o.target_release)),'release-_ v') = '19' JOIN disposition dp ON dp.target = o.id JOIN resolution rs ON rs.id = dp.resolution_id JOIN meeting m ON m.id = rs.meeting_id JOIN packs p ON p.cr = o.id JOIN cr_pack cp ON cp.id = p.pack_id WHERE o.id NOT IN (SELECT id FROM anchor) AND COALESCE(o.number, '') <> '{ANCHOR}' AND o.id <> '{ANCHOR}' AND replace(replace(replace(replace(lower(trim(dp.evidence_status)),'-',''),'_',''),' ',''),'#','') = 'sourceverified' AND replace(replace(replace(replace(lower(trim(dp.scope)),'-',''),'_',''),' ',''),'#','') IN ('wholedocument','document','wholedoc','entiredocument','fulldocument') AND replace(replace(replace(replace(lower(trim(m.wg)),'-',''),'_',''),' ',''),'#','') IN ('ran2','r2','ranwg2','tsgranwg2','tsgr2','wg2')
